function Box(item) {
  this.item = item;
  if (item === "gift") {
    return Object.create(Box.prototype);
  }
  if (item === "empty") {
    return {};
  }
}

const a = new Box("book");
const b = new Box("gift");
const c = new Box("empty");

console.log(a instanceof Box, b instanceof Box, c instanceof Box);
console.log(a.item, b.item, c.item);
console.log(b.constructor === Box, c.constructor === Object);
